import pandas as pd
import matplotlib.pyplot as plt

# 1. Load the CSV log generated by your simulation
df = pd.read_csv("plant_simulation_log.csv")

# 2. Create a clean multi-subplot figure for engineering analysis
plt.figure(figsize=(12, 8))

# Subplot 1: Temperatures (Inlet, Unit 1 Outlet, Unit 2 Outlet vs Target)
plt.subplot(2, 1, 1)
plt.plot(df["time_min"], df["inlet_temp"], label="Inlet Temp (°C)", color="blue", linestyle="--")
plt.plot(df["time_min"], df["u1_outlet"], label="Unit 1 Outlet (~100°C)", color="orange")
plt.plot(df["time_min"], df["u2_outlet"], label="Unit 2 Outlet (Target 120°C)", color="green", linewidth=2)
plt.axhline(y=120.0, color="red", linestyle=":", label="Target Setpoint (120°C)")
plt.title("Autonomous Multi-Agent Coupled Plant Simulation: Thermal Response", fontsize=14, fontweight="bold")
plt.ylabel("Temperature (°C)")
plt.legend(loc="upper right")
plt.grid(True)

# Subplot 2: Economic OPEX & Scope 1 Emissions Cost
plt.subplot(2, 1, 2)
plt.plot(df["time_min"], df["opex"], label="Total Hourly OPEX ($/hr)", color="purple")
plt.title("Economic Audit: Hourly OPEX & Carbon Tax Load", fontsize=14, fontweight="bold")
plt.xlabel("Simulation Time (Minutes)")
plt.ylabel("OPEX ($/hr)")
plt.legend(loc="upper right")
plt.grid(True)

plt.tight_layout()

# 3. Save and show the plot
plt.savefig("plant_performance_plot.png", dpi=300)
print("=== PLOT SUCCESSFULLY GENERATED AND SAVED AS 'plant_performance_plot.png' ===")
plt.show()